    int $monthsPerQuarter
): array {
    $this->roundingMetaUnits = [
        'millennium' => [$yearsPerMillennium, 'year'],
        'century' => [$yearsPerCentury, 'year'],
        'decade' => [$yearsPerDecade, 'year'],
        'quarter' => [$monthsPerQuarter, 'month'],
        'millisecond' => [1000, 'microsecond'],
