     */
    public function shares($divider)
    {
        $this->intervalUnitSnapshot = $this->captureUnitSnapshot();
        return $this->times(1 / $divider);
    }

    protected function copyProperties(self $interval, $ignoreSign = false)
    {
        $this->years = $interval->years;
